// ── Per-build arch case ──────────────────────────────────────────────
// Exactly one device backend is compiled per .so (setup.py picks CUDA xor
// HIP), so only that backend's namespace (sg::sm90 / sg::gfx942) has DEFINED
// symbols at link time. Emitting the other arch's case still references its
// non-template functions (e.g. sg::gfx942::moe_filter_active_params, defined
// only in the HIP .hip TUs) — which leaves them undefined and the .so fails to
// load under RTLD_NOW. `#if` cannot live inside a macro body, so gate the case
// at definition time by the build macro. detect_arch() returns the live arch
// at runtime, so the compiled-out case is never reachable anyway; an arch that
// doesn't match the compiled backend falls through to the `default:` throw.
#if defined(WITH_HIP)
#  define SG_ARCH_CASE_RET(METHOD, ...)  case 942: return ::sg::gfx942::METHOD(__VA_ARGS__);
#  define SG_ARCH_CASE_VOID(METHOD, ...) case 942: ::sg::gfx942::METHOD(__VA_ARGS__); break;
#else
#  define SG_ARCH_CASE_RET(METHOD, ...)  case 90:  return ::sg::sm90::METHOD(__VA_ARGS__);
#  define SG_ARCH_CASE_VOID(METHOD, ...) case 90:  ::sg::sm90::METHOD(__VA_ARGS__); break;
#endif

// ── Dispatch macro: returns from enclosing function ──────────────────
#define SG_DISPATCH(METHOD, ...) \
    do { \
        const int sg_arch_ = ::sg::detect_arch(); \
        switch (sg_arch_) { \
            SG_ARCH_CASE_RET(METHOD, ##__VA_ARGS__) \
            default: \
                throw std::runtime_error( \
                    std::string(#METHOD) + " dispatch: unsupported arch " + \
                    std::to_string(sg_arch_)); \
        } \
    } while (0)

