namespace fused {
// The persistent-megakernel scratch the host zero-initializes (mirror of
// csrc/fused/megakernel_common.cuh::PersistentContext — kept layout-identical).
// MUST live in sg::fused (NOT sg::fused::sm90): the real type the generated
// cells compile against is sg::fused::PersistentContext (megakernel_common.cuh
// opens `namespace sg { namespace fused {`). fused_dispatch_table.inc below is
// included within sg::fused::sm90, so its unqualified `PersistentContext`
// resolves to this enclosing-namespace type — matching the cell definitions'
// mangled signatures. Nesting it under sm90 forked the type and left every
// sg::fused::sm90::mega_* call referencing an undefined sm90-qualified symbol.
struct PersistentContext {
 int* g_next_task;
 unsigned* g_arrived;
 unsigned* g_generation;
 int n_tasks;
 unsigned n_ctas;
};
} // namespace fused

